ga_7(){return"\u06a9\u0627\u062a\u06ce\u06a9 \u06a9\u0648\u0698\u0627\u0648\u06d5\u062a\u06d5\u0648\u06d5\u060c \u0626\u06d5\u0645 \u062a\u0627\u0642\u06cc\u06af\u06d5\u06cc\u06d5 \u062f\u06d5\u0631\u0646\u0627\u06a9\u06d5\u0648\u06ce\u062a \u06a9\u0627\u062a\u06ce\u06a9 \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06ce\u06a9 \u0628\u06d5\u062f\u0648\u0627\u06cc \u062a\u0627\u0642\u06cc\u06af\u06d5\u06cc\u06d5\u06a9\u062f\u0627 \u062f\u06d5\u06af\u06d5\u0695\u06ce\u062a \u0628\u06c6 \u067e\u06d5\u06cc\u0648\u06d5\u0633\u062a\u0628\u0648\u0648\u0646\u060c \u0648\u06d5 \u0647\u06cc\u0686 \u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u062f\u0646\u06cc \u062e\u06c6\u06a9\u0627\u0631\u0627\u0646\u06d5\u06cc \u0646\u0648\u06ce\u06cc \u062f\u06a9\u062a\u06c6\u0631/\u06a9\u0644\u06cc\u0646\u06cc\u06a9 \u0648\u06d5\u0631\u0646\u0627\u06af\u0631\u06ce\u062a."},
gZD(){return"\u0634\u0627\u0631\u062f\u0646\u06d5\u0648\u06d5\u06cc \u06a9\u06d5\u06cc\u0633\u06d5 \u0647\u06d5\u06b5\u0648\u06d5\u0634\u06ce\u0646\u0631\u0627\u0648\u06d5\u06a9\u0627\u0646 \u0644\u06d5 \u062a\u06d5\u062e\u062a\u06d5\u06cc \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u0627\u0646"},
gZE(){return"\u06a9\u0627\u062a\u06ce\u06a9 \u06a9\u0627\u0631\u0627 \u0628\u06ce\u062a\u060c \u06a9\u06d5\u06cc\u0633\u06cc \u0647\u06d5\u06b5\u0648\u06d5\u0634\u06ce\u0646\u0631\u0627\u0648 \u0628\u06d5 \u062a\u06d5\u0648\u0627\u0648\u06cc \u0644\u06d5 \u062a\u06d5\u062e\u062a\u06d5\u06cc \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u0627\u0646 \u062f\u06d5\u0631\u0646\u0627\u06a9\u06d5\u0648\u06ce\u062a\u060c \u0644\u06d5 \u062c\u06cc\u0627\u062a\u06cc \u0626\u06d5\u0648\u06d5\u06cc \u06a9\u0627\u06b5 \u062f\u06cc\u0627\u0631 \u0628\u06ce\u062a \u0644\u06d5 \u0633\u062a\u0648\u0648\u0646\u06cc \u0642\u06c6\u0646\u0627\u063a\u06d5\u06a9\u06d5\u06cc. \u0647\u06d5\u0631\u0648\u06d5\u0647\u0627 \u0628\u06d5 \u062a\u06d5\u0648\u0627\u0648\u06cc \u062f\u06d5\u062a\u0648\u0627\u0646\u0631\u06ce\u062a \u0628\u06af\u06d5\u0695\u062f\u0631\u06ce\u062a \u0628\u06c6\u06cc \u0644\u06d5 \u0647\u06d5\u0645\u0648\u0648 \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u0627\u0646."},
gZH(){return"\u0698\u0645\u0627\u0631\u06d5\u06cc\u06d5\u06a9\u06cc \u062f\u0631\u0648\u0633\u062a\u06cc \u0695\u06c6\u0698 \u0628\u0646\u0648\u0648\u0633\u06d5 (\u0632\u06cc\u0627\u062a\u0631 \u0644\u06d5 0)."},
ga_m(){return"\u0634\u0648\u06ce\u0646\u06a9\u06d5\u0648\u062a\u0646\u06cc \u0633\u06d5\u0631\u062f\u0627\u0646\u06cc \u0645\u0646\u062f\u0648\u0648\u0628"},
ga_n(){return'\u0686\u06d5\u0646\u062f \u0695\u06c6\u0698 \u062f\u06d5\u0628\u06ce\u062a \u062a\u06ce\u067e\u06d5\u0695\u06ce\u062a \u0644\u06d5 \u062f\u0648\u0627\u06cc\u06cc\u0646 \u0633\u06d5\u0631\u062f\u0627\u0646\u06cc \u0645\u0646\u062f\u0648\u0648\u0628 \u0628\u06c6 \u062f\u06a9\u062a\u06c6\u0631\u06ce\u06a9 \u067e\u06ce\u0634 \u0626\u06d5\u0648\u06d5\u06cc \u0626\u06d5\u0648 \u062f\u06a9\u062a\u06c6\u0631\u06d5 \u062f\u0648\u0648\u0628\u0627\u0631\u06d5 \u0648\u06d5\u06a9 "\u067e\u06ce\u0648\u06cc\u0633\u062a\u06cc \u0628\u06d5 \u0633\u06d5\u0631\u062f\u0627\u0646 \u0647\u06d5\u06cc\u06d5" \u0646\u06cc\u0634\u0627\u0646 \u0628\u062f\u0631\u06ce\u062a \u0644\u06d5 \u062a\u0627\u0628\u06cc \u0633\u06d5\u0631\u062f\u0627\u0646\u06d5\u06a9\u0627\u0646.'},
